-- Montaj olayları (AppSheet AssemblyEvents -> montaj_sessions)
--
-- Status CLOSE -> tamamlandi, OPEN -> montajda.
-- Status boş olanlarda EndTime doluysa tamamlandi, değilse montajda.
-- Tekrarlayan EventID'ler ve SKU/StepID'si boş satırlar elendi.
-- step_name / seq_no / is_final_step assembly_steps'ten dolduruluyor.

ON CONFLICT (session_id) DO NOTHING;

ON CONFLICT (session_id) DO NOTHING;

-- Adım bilgilerini montaj adımları tablosundan tamamla
UPDATE public.montaj_sessions m
SET step_name = s.step_name, seq_no = s.seq_no, is_final_step = s.is_final_step
FROM public.assembly_steps s
WHERE s.step_id = m.step_id AND m.step_name IS NULL;

-- Operatör adlarını kullanıcı tablosundan tamamla
UPDATE public.montaj_sessions m
SET operator_name = u.full_name
FROM public.users u
WHERE u.user_id = m.operator_id AND m.operator_name IS NULL;
